CREATE TRIGGER sync_projects_insert AFTER INSERT ON projects
WHEN NOT EXISTS (SELECT 1 FROM sync_meta WHERE "key" = 'applying')
BEGIN
  INSERT INTO sync_outbox (entity, row_key, changed_at) VALUES ('projects', NEW.uuid, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) ON CONFLICT (entity, row_key) DO UPDATE SET changed_at = excluded.changed_at;
END;

