END;

CREATE TRIGGER sync_projects_delete AFTER DELETE ON projects
WHEN NOT EXISTS (SELECT 1 FROM sync_meta WHERE "key" = 'applying') AND OLD.uuid IS NOT NULL
BEGIN
  DELETE FROM sync_outbox WHERE entity = 'projects' AND row_key = OLD.uuid;
  INSERT INTO sync_tombstones (entity, doc_id, deleted_at) VALUES ('projects', OLD.uuid, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) ON CONFLICT (entity, doc_id) DO UPDATE SET deleted_at = excluded.deleted_at;
END;

